#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, h;
    cin >> n >> h;

    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, -1));
    dp[0][0] = 1;

    function<long long(int, int)> f = [&](int n, int h) -> long long {
        if (dp[n][h] != -1) {
            return dp[n][h];
        }
        if (n == 0) {
            return 0;
        }
        if (h == 0) {
            return f(n, 1);
        }
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            ans += f(n - i - 1, 0) * f(i, h - 1);
            ans += f(n - i - 1, h - 1) * f(i, 0);
            ans -= f(n - i - 1, h - 1) * f(i, h - 1);
        }
        dp[n][h] = ans;
        return ans;
    };

    cout << f(n, h) << endl;
    return 0;
}
